export type PublishErrors = {
    /**
     * No usable credential
     */
    401: Problem;
    /**
     * No `publish` scope in that channel
     */
    403: Problem;
    /**
     * The payload does not validate
     */
    422: Problem;
    /**
     * Over the publish quota
     */
    429: Problem;
};

export type PublishError = PublishErrors[keyof PublishErrors];

export type PublishResponses = {
    /**
     * Replay of an earlier identical request
     */
    200: Published;
    /**
     * Published
     */
    201: Published;
};

export type PublishResponse = PublishResponses[keyof PublishResponses];

