export type StreamData = {
    body?: never;
    headers?: {
        /**
         * The cursor of the last event received. Sent automatically by browsers on reconnect; replays exactly what was missed.
         */
        'Last-Event-ID'?: string | null;
    };
    path?: never;
    query?: {
        /**
         * Comma-separated channel ids; absent means every channel the caller may read.
         */
        channels?: string;
        /**
         * Resume after this cursor. `Last-Event-ID` wins over it when both are sent,
         * because that one is the browser reconnecting rather than the page asking.
         */
        cursor?: string;
        /**
         * Which device is connected, so its cursor advances as it reads.
         */
        device?: string;
    };
    url: '/api/v1/stream';
};

export type StreamErrors = {
    /**
     * No usable credential
     */
    401: Problem;
    /**
     * Not a device owner — service accounts read the inbox
     */
    403: Problem;
    /**
     * That cursor is not one of ours
     */
    422: Problem;
};

export type StreamError = StreamErrors[keyof StreamErrors];

export type StreamResponses = {
    /**
     * An event stream
     */
    200: unknown;
};

export type SyncData = {
    body?: never;
    path?: never;
    query?: {
        /**
         * Resume after this cursor. Absent replays everything still retained.
         */
        cursor?: string;
        /**
         * Comma-separated channel ids; absent means every channel the caller may read.
         */
        channels?: string;
        /**
         * Which device is catching up, so its cursor is advanced. Absent for a one-off
         * caller — `curl /sync` from a shell has no cursor to keep.
         */
        device?: string;
        /**
         * Page size, clamped server-side.
         */
        limit?: number;
    };
    url: '/api/v1/sync';
};

export type SyncErrors = {
    /**
     * No usable credential
     */
    401: Problem;
    /**
     * Not a device owner — service accounts read the inbox
     */
    403: Problem;
    /**
     * That cursor is not one of ours
     */
    422: Problem;
};

export type SyncError = SyncErrors[keyof SyncErrors];

export type SyncResponses = {
    /**
     * Events since the cursor, plus what expired while away
     */
    200: SyncPage;
};

export type SyncResponse = SyncResponses[keyof SyncResponses];

